class Solution:

	def Reduced_String(self, k, s):
		if k == 1:
			return ''
		count = 1
		stack = ['A']
		for elm in s:
			if stack == [0] or stack[-1] != elm:
				stack.append(elm)
			else:
				i = -1
				while stack[i] == elm and count < k:
					count += 1
					i -= 1
				if count == k:
					while count > 1:
						stack.pop()
						count -= 1
				else:
					stack.append(elm)
					count = 1
		return ''.join(stack)[1:]
